import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Video Game","description":"","frontmatter":{},"headers":[],"relativePath":"demos/VIDEO_GAME.md","filePath":"demos/VIDEO_GAME.md"}'),s={name:"demos/VIDEO_GAME.md"};function o(i,e,l,h,d,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="video-game" tabindex="-1">Video Game <a class="header-anchor" href="#video-game" aria-label="Permalink to &quot;Video Game&quot;">​</a></h1><p>The demo songs in the video game style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#dangerous_to_go_alone">Adventure Game Themes</a>: <code>dangerous_to_go_alone.yml</code></li><li><a href="#fang_removal">Gothic Stage Theme</a>: <code>fang_removal.yml</code></li><li><a href="#in_another_castle">Platform Game Themes</a>: <code>in_another_castle.yml</code></li><li><a href="#incoming_message">Ten Stages</a>: <code>incoming_message.yml</code></li></ul><p><a id="dangerous_to_go_alone"></a></p><h2 id="adventure-game-themes-dangerous-to-go-alone-yml" tabindex="-1">Adventure Game Themes: <code>dangerous_to_go_alone.yml</code> <a class="header-anchor" href="#adventure-game-themes-dangerous-to-go-alone-yml" aria-label="Permalink to &quot;Adventure Game Themes: `dangerous_to_go_alone.yml`&quot;">​</a></h2><p>An adventure game&#39;s two themes run end to end, a heroic overworld march and an eerie dungeon, in the manner of The Legend of Zelda&#39;s overworld and dungeon themes (Koji Kondo), with tunes of its own. A fanfare on I, VII, VI and V; the march, its second strain and the march again; a fall down the stairs; the dungeon&#39;s figure on i VII VI V, then with its slow tune; a climb back; the march once more with everything.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/dangerous_to_go_alone.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/dangerous_to_go_alone.yml</code></a> · D major · 140 BPM · 2:54 · 14 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="fang_removal"></a></p><h2 id="gothic-stage-theme-fang-removal-yml" tabindex="-1">Gothic Stage Theme: <code>fang_removal.yml</code> <a class="header-anchor" href="#gothic-stage-theme-fang-removal-yml" aria-label="Permalink to &quot;Gothic Stage Theme: `fang_removal.yml`&quot;">​</a></h2><p>A gothic eight-bit stage theme in the manner of Castlevania&#39;s Vampire Killer (Kinuyo Yamashita and Satoe Terashima), with a melody of its own. Three voices and noise, as the old console had: a square lead with a jumping, syncopated tune, a bass in octaves in sixteenths, and a second square that plays each chord as a fast arpeggio; the chords fall i VII VI to a major V.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/fang_removal.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/fang_removal.yml</code></a> · E minor · 150 BPM · 2:59 · 11 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="in_another_castle"></a></p><h2 id="platform-game-themes-in-another-castle-yml" tabindex="-1">Platform Game Themes: <code>in_another_castle.yml</code> <a class="header-anchor" href="#platform-game-themes-in-another-castle-yml" aria-label="Permalink to &quot;Platform Game Themes: `in_another_castle.yml`&quot;">​</a></h2><p>A platform game&#39;s four worlds and a victory, each with sounds of its own, in the manner of the themes of Super Mario Bros. (Koji Kondo), with tunes of its own. World one, the bouncing tune and its middle; a pipe down; world two, the underground riff, then with a creeping answer; a pipe; world three, the waltz twice, the second time with harp and strings; a pipe; the castle; the victory fanfare and a last chord.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/in_another_castle.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/in_another_castle.yml</code></a> · G major · 100 BPM · 3:05 · 15 scenes · 21 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="incoming_message"></a></p><h2 id="ten-stages-incoming-message-yml" tabindex="-1">Ten Stages: <code>incoming_message.yml</code> <a class="header-anchor" href="#ten-stages-incoming-message-yml" aria-label="Permalink to &quot;Ten Stages: `incoming_message.yml`&quot;">​</a></h2><p>Nine minutes after Mega Man 2&#39;s intro and boss themes (Takashi Tateishi): ten stages, each a theme of its own, ending on the first. Ten stages, each in a key of its own, changing theme exactly nine times, with a one-bar fill and a rising chip arpeggio between each, and the last a reprise of the first with everything playing. Every theme is its own. Each stage&#39;s patterns are named after it, stage_0 to stage_9, and a Progression of sixteen chords carries each stage&#39;s bass, arpeggio and guitar.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/incoming_message.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/incoming_message.yml</code></a> · E minor · 150 BPM · 8:46 · 29 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table>',23)])])}const y=t(s,[["render",o]]);export{m as __pageData,y as default};
